"""
Record Webhook Result — append one per-target event (loop script).

  argv[1]  Local - Processed List
  argv[2]  Local - Current Target ID
  argv[3]  Target Type
  argv[4]  Local - Loop Status Code
  argv[5]  Local - Loop Error Message
  argv[6]  Local - Loop Performed Operation
  argv[7]  Mode
  argv[8]  Dry-Run

Script query: updated_list
"""

import sys
import json

SUCCESS_CODES = frozenset({"200","201","204"})
OK_OUTCOMES = frozenset({"updated", "created", "deleted", "skipped"})
VALID_ACTIONS = frozenset({"update", "create", "delete", "get", "skip"})


def parse_list(raw):
    try:
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def is_success(status_code):
    return str(status_code).strip() in SUCCESS_CODES


def resolve_outcome(action, status_code):
    action = action.strip().lower()

    if action not in VALID_ACTIONS:
        return "invalid", "Unknown or missing loop operation"

    if action == "skip":
        return "skipped", "Webhook URL not found on target"

    if action == "get":
        if is_success(status_code):
            return "invalid", "Get webhooks succeeded in failure branch"
        return "get_failed", "Failed to list webhooks for target"

    if is_success(status_code):
        labels = {
            "update": ("updated", "Webhook updated successfully"),
            "create": ("created", "Webhook created successfully"),
            "delete": ("deleted", "Webhook deleted successfully"),
        }
        return labels[action]

    labels = {
        "update": ("apply_failed", "Webhook update failed"),
        "create": ("apply_failed", "Webhook create failed"),
        "delete": ("apply_failed", "Webhook delete failed"),
    }
    return labels[action]


def build_message(base_message, status_code, status_message):
    message = base_message
    code = str(status_code).strip()
    detail = str(status_message).strip()
    if code:
        message += " (HTTP " + code + ")"
    if detail:
        message += " — " + detail
    return message


def parse_bool(raw):
    return str(raw).strip().lower() in ("true", "1", "yes")


def dry_run_message(outcome, base_message):
    labels = {
        "updated": "Would update webhook (dry-run - no changes applied)",
        "created": "Would create webhook (dry-run - no changes applied)",
        "deleted": "Would delete webhook (dry-run - no changes applied)",
        "skipped": "Would skip — webhook URL not found on target",
    }
    return labels.get(outcome, base_message)


results = parse_list(sys.argv[1] if len(sys.argv) > 1 else "[]")

target_id = (sys.argv[2] if len(sys.argv) > 2 else "").strip()
target_type = (sys.argv[3] if len(sys.argv) > 3 else "").strip().lower()
status_code = (sys.argv[4] if len(sys.argv) > 4 else "").strip()
status_message = (sys.argv[5] if len(sys.argv) > 5 else "").strip()
action = (sys.argv[6] if len(sys.argv) > 6 else "").strip().lower()
mode = (sys.argv[7] if len(sys.argv) > 7 else "").strip().lower()
dry_run = parse_bool(sys.argv[8] if len(sys.argv) > 8 else "")

outcome, base_message = resolve_outcome(action, status_code)
if dry_run and outcome in OK_OUTCOMES:
    base_message = dry_run_message(outcome, base_message)
message = build_message(base_message, status_code, status_message)

entry = {
    "targetId": target_id,
    "targetType": target_type,
    "mode": mode,
    "outcome": outcome,
    "success": outcome in OK_OUTCOMES,
    "message": message,
}

if dry_run:
    entry["dryRun"] = True

if status_code:
    entry["httpStatus"] = status_code

results.append(entry)
updated_list = json.dumps(results, separators=(",", ":"))

"""
Format Webhook Report — final workflow outputs.

  argv[1]  Local - Processed List
  argv[2]  Mode
  argv[3]  Target Type
  argv[4]  Dry-Run

Script queries:
  report, status_message, status_code, error_message, result_json
"""

import sys
import json

OK_OUTCOMES = frozenset({"updated", "created", "deleted", "skipped"})


def parse_list(raw):
    try:
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def item_message(item):
    return str(item.get("message") or item.get("description") or "").strip()


def item_success(item):
    if "success" in item:
        return bool(item.get("success"))
    return str(item.get("outcome", "")).lower() in OK_OUTCOMES


def count_outcomes(targets):
    counts = {
        "updated": 0,
        "created": 0,
        "deleted": 0,
        "skipped": 0,
        "failed": 0,
    }
    for item in targets:
        outcome = str(item.get("outcome", "invalid")).lower()
        if outcome in counts:
            counts[outcome] += 1
        else:
            counts["failed"] += 1
    return counts


def overall_status(targets):
    if not targets:
        return "Failed"
    failed = sum(1 for target in targets if not item_success(target))
    if failed == 0:
        return "Success"
    if failed < len(targets):
        return "Partial"
    return "Failed"


def status_code_for(status):
    if status == "Success":
        return "200"
    if status == "Partial":
        return "207"
    return "500"


def build_report(mode, target_type, status, counts, targets, dry_run=False):
    lines = [
        "Webhook Bulk Report",
        "Mode: " + mode,
        "Target type: " + target_type,
        "Dry-Run: " + ("yes - no changes were applied" if dry_run else "no"),
        "Status: " + status,
        "",
        "Updated:  " + str(counts["updated"]),
        "Created:  " + str(counts["created"]),
        "Deleted:  " + str(counts["deleted"]),
        "Skipped:  " + str(counts["skipped"]),
        "Failed:   " + str(counts["failed"]),
        "",
        "Details",
        "-" * 40,
    ]

    if not targets:
        lines.append("No targets processed.")
    else:
        for item in sorted(targets, key=lambda x: str(x.get("targetId", "")).lower()):
            target_id = item.get("targetId", "unknown")
            outcome = item.get("outcome", "invalid")
            message = item_message(item)
            line = target_id + " — " + outcome
            if message:
                line += " — " + message
            lines.append(line)

    return "\n".join(lines)


def parse_bool(raw):
    return str(raw).strip().lower() in ("true", "1", "yes")


report = "Error generating report."
status_message = "Failed"
status_code = "500"
error_message = "Error generating report."
result_json = "{}"

try:
    targets = parse_list(sys.argv[1] if len(sys.argv) > 1 else "[]")
    mode = (sys.argv[2] if len(sys.argv) > 2 else "update").strip().lower()
    target_type = (sys.argv[3] if len(sys.argv) > 3 else "networks").strip().lower()
    dry_run = parse_bool(sys.argv[4] if len(sys.argv) > 4 else "")

    counts = count_outcomes(targets)
    status_message = overall_status(targets)
    status_code = status_code_for(status_message)

    if status_message == "Success":
        error_message = ""
    elif not targets:
        error_message = "No targets were processed."
    else:
        error_message = str(counts["failed"]) + " target(s) failed."

    report = build_report(mode, target_type, status_message, counts, targets, dry_run)

    result_json = json.dumps(
        {
            "overallStatus": status_message,
            "mode": mode,
            "targetType": target_type,
            "dryRun": dry_run,
            "total": len(targets),
            "counts": counts,
            "targets": sorted(
                targets,
                key=lambda x: str(x.get("targetId", "")).lower(),
            ),
        },
        separators=(",", ":"),
    )

except Exception as exc:
    script_error = "Error generating report: " + str(exc)
    report = script_error
    status_message = "Failed"
    status_code = "500"
    error_message = script_error
    result_json = json.dumps(
        {
            "overallStatus": "Failed",
            "mode": (sys.argv[2] if len(sys.argv) > 2 else "update").strip().lower(),
            "targetType": (sys.argv[3] if len(sys.argv) > 3 else "networks").strip().lower(),
            "total": 0,
            "counts": {},
            "targets": [],
            "error": script_error,
        },
        separators=(",", ":"),
    )
